// Diagnostic actual shader read; owner and all temporary objects retire after queue idle.
inline void testVulkanLightShaderRecordsCandidate(HMODULE library,VkDevice device,VkPhysicalDevice physical,uint32_t family,const std::vector<uint32_t>&words){
 if(words.empty()||words.size()%28||words.size()/28>UINT32_MAX)throw std::runtime_error("light readback record count");
 uint32_t recordCount=uint32_t(words.size()/28);size_t byteCount=words.size()*sizeof(uint32_t);
 VkPhysicalDeviceProperties caps{};load<PFN_vkGetPhysicalDeviceProperties>(library,"vkGetPhysicalDeviceProperties")(physical,&caps);if(recordCount>caps.limits.maxComputeWorkGroupCount[0])throw std::runtime_error("light readback dispatch range");
 std::vector<uint32_t>zero(words.size());VulkanProjectedLightBufferCandidate input(library,device),output(library,device);input.create(physical,words.data(),byteCount);output.create(physical,zero.data(),byteCount);
 VkDescriptorSetLayout setLayout{};VkDescriptorPool descriptors{};VkPipelineLayout layout{};VkShaderModule shader{};VkPipeline pipeline{};VkCommandPool commands{};VkQueue queue{};bool submitted=false;
 load<PFN_vkGetDeviceQueue>(library,"vkGetDeviceQueue")(device,family,0,&queue);
 auto check=VulkanProjectedLightBufferCandidate::check;
 auto cleanup=[&]{if(submitted)load<PFN_vkQueueWaitIdle>(library,"vkQueueWaitIdle")(queue);if(commands)load<PFN_vkDestroyCommandPool>(library,"vkDestroyCommandPool")(device,commands,nullptr);if(pipeline)load<PFN_vkDestroyPipeline>(library,"vkDestroyPipeline")(device,pipeline,nullptr);if(shader)load<PFN_vkDestroyShaderModule>(library,"vkDestroyShaderModule")(device,shader,nullptr);if(layout)load<PFN_vkDestroyPipelineLayout>(library,"vkDestroyPipelineLayout")(device,layout,nullptr);if(descriptors)load<PFN_vkDestroyDescriptorPool>(library,"vkDestroyDescriptorPool")(device,descriptors,nullptr);if(setLayout)load<PFN_vkDestroyDescriptorSetLayout>(library,"vkDestroyDescriptorSetLayout")(device,setLayout,nullptr);};
 try{
  VkDescriptorSetLayoutBinding bindings[2]{{3,VK_DESCRIPTOR_TYPE_STORAGE_BUFFER,1,VK_SHADER_STAGE_COMPUTE_BIT,nullptr},{5,VK_DESCRIPTOR_TYPE_STORAGE_BUFFER,1,VK_SHADER_STAGE_COMPUTE_BIT,nullptr}};
  VkDescriptorSetLayoutCreateInfo si{};si.sType=VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO;si.bindingCount=2;si.pBindings=bindings;check(load<PFN_vkCreateDescriptorSetLayout>(library,"vkCreateDescriptorSetLayout")(device,&si,nullptr,&setLayout));
  VkDescriptorPoolSize size{VK_DESCRIPTOR_TYPE_STORAGE_BUFFER,2};VkDescriptorPoolCreateInfo pi{};pi.sType=VK_STRUCTURE_TYPE_DESCRIPTOR_POOL_CREATE_INFO;pi.maxSets=1;pi.poolSizeCount=1;pi.pPoolSizes=&size;check(load<PFN_vkCreateDescriptorPool>(library,"vkCreateDescriptorPool")(device,&pi,nullptr,&descriptors));
  VkDescriptorSet set{};VkDescriptorSetAllocateInfo ai{};ai.sType=VK_STRUCTURE_TYPE_DESCRIPTOR_SET_ALLOCATE_INFO;ai.descriptorPool=descriptors;ai.descriptorSetCount=1;ai.pSetLayouts=&setLayout;check(load<PFN_vkAllocateDescriptorSets>(library,"vkAllocateDescriptorSets")(device,&ai,&set));
  VkDescriptorBufferInfo buffers[2]{input.descriptor(),output.descriptor()};VkWriteDescriptorSet writes[2]{};for(unsigned i=0;i<2;++i){writes[i].sType=VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET;writes[i].dstSet=set;writes[i].dstBinding=i?5:3;writes[i].descriptorCount=1;writes[i].descriptorType=VK_DESCRIPTOR_TYPE_STORAGE_BUFFER;writes[i].pBufferInfo=&buffers[i];}load<PFN_vkUpdateDescriptorSets>(library,"vkUpdateDescriptorSets")(device,2,writes,0,nullptr);
  VkPipelineLayoutCreateInfo li{};li.sType=VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;li.setLayoutCount=1;li.pSetLayouts=&setLayout;check(load<PFN_vkCreatePipelineLayout>(library,"vkCreatePipelineLayout")(device,&li,nullptr,&layout));
  std::ifstream f(editorShaderResourcePathCandidate("build/session-core/sfm64-light-buffer-readback.spv"),std::ios::binary|std::ios::ate);if(!f)throw std::runtime_error("light readback shader missing");auto length=f.tellg();if(length<=0||uint64_t(length)%4)throw std::runtime_error("light shader size");std::vector<uint32_t>code(size_t(length)/4);f.seekg(0);f.read(reinterpret_cast<char*>(code.data()),length);if(!f)throw std::runtime_error("light shader read");VkShaderModuleCreateInfo mi{};mi.sType=VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;mi.codeSize=size_t(length);mi.pCode=code.data();check(load<PFN_vkCreateShaderModule>(library,"vkCreateShaderModule")(device,&mi,nullptr,&shader));
  VkComputePipelineCreateInfo ci{};ci.sType=VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO;ci.layout=layout;ci.stage.sType=VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;ci.stage.stage=VK_SHADER_STAGE_COMPUTE_BIT;ci.stage.module=shader;ci.stage.pName="main";check(load<PFN_vkCreateComputePipelines>(library,"vkCreateComputePipelines")(device,VK_NULL_HANDLE,1,&ci,nullptr,&pipeline));
  VkCommandPoolCreateInfo cp{};cp.sType=VK_STRUCTURE_TYPE_COMMAND_POOL_CREATE_INFO;cp.queueFamilyIndex=family;check(load<PFN_vkCreateCommandPool>(library,"vkCreateCommandPool")(device,&cp,nullptr,&commands));VkCommandBuffer command{};VkCommandBufferAllocateInfo ca{};ca.sType=VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO;ca.commandPool=commands;ca.level=VK_COMMAND_BUFFER_LEVEL_PRIMARY;ca.commandBufferCount=1;check(load<PFN_vkAllocateCommandBuffers>(library,"vkAllocateCommandBuffers")(device,&ca,&command));
  VkCommandBufferBeginInfo bi{};bi.sType=VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO;check(load<PFN_vkBeginCommandBuffer>(library,"vkBeginCommandBuffer")(command,&bi));load<PFN_vkCmdBindPipeline>(library,"vkCmdBindPipeline")(command,VK_PIPELINE_BIND_POINT_COMPUTE,pipeline);load<PFN_vkCmdBindDescriptorSets>(library,"vkCmdBindDescriptorSets")(command,VK_PIPELINE_BIND_POINT_COMPUTE,layout,0,1,&set,0,nullptr);load<PFN_vkCmdDispatch>(library,"vkCmdDispatch")(command,recordCount,1,1);
  VkMemoryBarrier barrier{};barrier.sType=VK_STRUCTURE_TYPE_MEMORY_BARRIER;barrier.srcAccessMask=VK_ACCESS_SHADER_WRITE_BIT;barrier.dstAccessMask=VK_ACCESS_HOST_READ_BIT;load<PFN_vkCmdPipelineBarrier>(library,"vkCmdPipelineBarrier")(command,VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT,VK_PIPELINE_STAGE_HOST_BIT,0,1,&barrier,0,nullptr,0,nullptr);check(load<PFN_vkEndCommandBuffer>(library,"vkEndCommandBuffer")(command));VkSubmitInfo submit{};submit.sType=VK_STRUCTURE_TYPE_SUBMIT_INFO;submit.commandBufferCount=1;submit.pCommandBuffers=&command;check(load<PFN_vkQueueSubmit>(library,"vkQueueSubmit")(queue,1,&submit,VK_NULL_HANDLE));submitted=true;check(load<PFN_vkQueueWaitIdle>(library,"vkQueueWaitIdle")(queue));submitted=false;
  void*mapped=nullptr;check(load<PFN_vkMapMemory>(library,"vkMapMemory")(device,output.memory,0,byteCount,0,&mapped));bool equal=std::memcmp(mapped,words.data(),byteCount)==0;load<PFN_vkUnmapMemory>(library,"vkUnmapMemory")(device,output.memory);if(!equal)throw std::runtime_error("shader light field readback mismatch");
  cleanup();std::cout<<"projected_light_shader_readback=passed records="<<recordCount<<" float_words="<<words.size()<<" byte_exact=1 lighting_draw=unverified\n";
 }catch(...){cleanup();throw;}
}

inline void testVulkanLightShaderReadbackCandidate(HMODULE library,VkDevice device,VkPhysicalDevice physical,uint32_t family,const std::array<uint32_t,84>*sourceWords=nullptr){
 std::vector<uint32_t>words(84);for(size_t i=0;i<words.size();++i)words[i]=0x3f000000u+uint32_t(i*131);
 if(sourceWords)std::copy(sourceWords->begin(),sourceWords->end(),words.begin());
 testVulkanLightShaderRecordsCandidate(library,device,physical,family,words);
}
